/// <summary>
/// AVA/WEN/2025/09/16 AVA_013109_InventSumTransfer
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormControlEventHandler(formControlStr(InventAdjInventOnHand, AVAValue), FormControlEventType::Clicked)]
public static void AVAValue_OnClicked(FormControl sender, FormControlEventArgs e)
{
    TmpFormLookUp   tmpFormLookup;
    FormDataSource  tmpFormLookUp_ds = sender.formRun().dataSource(formDataSourceStr(InventAdjInventOnHand,TmpFormLookUp));
    tmpFormLookup = tmpFormLookUp_ds.cursor();

    if (InventDataAdjSumUp::AVApromptPrice(tmpFormLookup))
    {
        tmpFormLookUp_ds.research();
    }

}
